def test_not_exported_with_braces_in_template_name(self, template_name):
    env = Environment(
        loader=DictLoader(
            {
                template_name: "{% from 'module' import missing %}{{ missing() }}",
                "module": "",
            }
        )
    )

    with pytest.raises(UndefinedError) as exc_info:
        env.get_template(template_name).render()

    assert str(exc_info.value) == (
